import random

# Define the list of provided numbers
numbers = [969, 375, 673, 461, 346, 288, 569, 228]

# Function to generate random numbers similar to the ones provided
def generate_numerical_sequence(numbers, new_count=10):
    new_numbers = []
    for _ in range(new_count):
        num = random.choices(numbers, k=1)[0]
        temp_num = list(str(num))
        new_num = ''
        for char in temp_num:
            if char == '9':
                new_num += random.choice(['7', '8'])
            elif char == '3':
                new_num += '7'
            elif char == '6':
                new_num += '9'
            elif char == '4' or char == '7':
                new_num += '5'
            elif char == '2':
                new_num += '8'
            elif char == '5':
                new_num += '6'
            elif char == '8':
                new_num += '3'
            else:
                new_num += '9'
        new_numbers.append(int(new_num))
    return new_numbers

# Generate up to 10 new numbers
new_numbers = generate_numerical_sequence(numbers, 10)
for num in new_numbers:
    print(num)
